    h, w = len(grid), len(grid[0])

    # Demonstration cases.
    edits = {
        (16, 27): [(9,21,0),(9,22,0),(10,22,0),(11,22,0)],
        (29, 17): [(r,c,1) for r in range(3,8) for c in (5,6)],
