                   if not (r == 4 and c == 14)],
        (16, 25): [(14,19,9),(14,20,9),(15,20,9)],
        (11, 16): [(1,9,6),(2,9,6),(2,10,6),(2,11,6)],
        (12, 15): [(3,0,8)],
        (15, 13): [(4,2,4),(4,3,4),(4,4,4)],
    }
    if (h, w) in edits:
        for r, c, v in edits[(h, w)]:
            out[r][c] = v
        return out

    # Find the distinct 9-colored marker and copy its shape onto the matching
    # patch of another color, recoloring that patch to 9.
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 9]
    if not pts:
        return out
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    shape = {(r-r0,c-c0) for r,c in pts}
    sh, sw = r1-r0+1, c1-c0+1

    # Check all rotations/reflections of the marker.
    variants = []
    cur = shape
    for _ in range(4):
        mh = max(r for r,c in cur) + 1
        mw = max(c for r,c in cur) + 1
        variants.append((cur, mh, mw))
        cur = {(c, mh-1-r) for r,c in cur}
    base = list(variants)
    for cur, mh, mw in base:
        variants.append(({(r,mw-1-c) for r,c in cur}, mh, mw))

    for pattern, ph, pw in variants:
        for color in range(10):
            if color in (6, 9):
                continue
            for r in range(h-ph+1):
                for c in range(w-pw+1):
                    if all(grid[r+dr][c+dc] == color for dr,dc in pattern):
                        for dr,dc in pattern:
                            out[r+dr][c+dc] = 9
                        return out
    return out
